// ---- helpers (shared by the workflows in this pack) ----
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const today = now.startOf('day');

// Read the first non-empty value among several possible column names.
const val = (row, ...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// Accepts 2026-11-20, 2026-11-20T14:30, 11/20/2026, 20.11.2026, Nov 20, 2026 or a Sheets serial number.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' })
      .setZone(zone, { keepLocalTime: true });
  }
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone });
  if (d.isValid) return d;
  d = DateTime.fromSQL(s, { zone });
  if (d.isValid) return d;
  for (const f of ['M/d/yyyy', 'M/d/yyyy H:mm', 'M/d/yyyy h:mm a', 'M/d/yy', 'd.M.yyyy', 'yyyy/M/d', 'd MMM yyyy', 'MMM d, yyyy', 'MMMM d, yyyy']) {
    d = DateTime.fromFormat(s, f, { zone });
    if (d.isValid) return d;
  }
  const js = new Date(s);
  return isNaN(js) ? null : DateTime.fromJSDate(js).setZone(zone);
}

// Whole days between a date and today (positive = in the past).
const daysAgo = (d) => Math.round(today.diff(d.startOf('day'), 'days').days);

const firstName = (name) => (String(name || '').trim().split(/\s+/)[0] || 'there');

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

function money(amount, currency) {
  const cur = (currency || cfg.currency || 'USD').toUpperCase();
  try {
    return new Intl.NumberFormat(cfg.locale || 'en-US', { style: 'currency', currency: cur }).format(toNumber(amount));
  } catch (e) {
    return cur + ' ' + toNumber(amount).toFixed(2);
  }
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const button = (url, label) => url
  ? `<p style="margin:24px 0"><a href="${esc(url)}" style="background:${cfg.brandColor || '#2563eb'};color:#ffffff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">${esc(label)}</a></p>`
  : '';

// Wraps body HTML in a clean, mobile-friendly email layout.
const layout = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">${inner}<p style="margin-top:32px;color:#6b7280;font-size:13px">${esc(cfg.businessName || '')}</p></div>`;
// ---- end helpers ----

const period = now.toFormat('yyyy-MM');
const due = today.plus({ days: Number(cfg.paymentTermsDays || 14) });
const out = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (!['yes', 'y', 'true', 'active'].includes(val(r, 'Active').toLowerCase())) return;
  const clientId = val(r, 'Client ID');
  const email = val(r, 'Client Email');
  if (!clientId || !email || toNumber(r['Monthly Fee']) <= 0) return;
  if (val(r, 'Last Invoiced') === period) return;          // already invoiced this month

  const invoiceId = `INV-${now.toFormat('yyyyMM')}-${clientId}`;
  const amount = money(r['Monthly Fee'], val(r, 'Currency'));
  const desc = val(r, 'Description') || 'Monthly retainer';
  const html = layout(`
    <table style="width:100%"><tr><td><h2 style="margin:0">Invoice</h2><div style="color:#6b7280">${esc(invoiceId)}</div></td>
    <td style="text-align:right;font-size:13px;color:#6b7280">Issued ${today.toFormat('d LLL yyyy')}<br><b style="color:#1f2937">Due ${due.toFormat('d LLL yyyy')}</b></td></tr></table>
    <p>Hi ${esc(firstName(val(r, 'Contact Name', 'Client Name')))},</p>
    <p>Please find your invoice for <b>${now.toFormat('LLLL yyyy')}</b> below.</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0">
      <tr style="background:#f9fafb"><th align="left" style="padding:10px;border-bottom:1px solid #e5e7eb">Description</th><th align="right" style="padding:10px;border-bottom:1px solid #e5e7eb">Amount</th></tr>
      <tr><td style="padding:10px;border-bottom:1px solid #e5e7eb">${esc(desc)} — ${now.toFormat('LLLL yyyy')}</td><td align="right" style="padding:10px;border-bottom:1px solid #e5e7eb">${amount}</td></tr>
      <tr><td style="padding:10px"><b>Total due</b></td><td align="right" style="padding:10px"><b>${amount}</b></td></tr>
    </table>
    ${button(val(r, 'Payment Link'), 'Pay ' + amount)}
    <p style="font-size:13px;color:#4b5563"><b>Other ways to pay:</b> ${esc(cfg.paymentInstructions || '')}<br>Please quote <b>${esc(invoiceId)}</b> as the reference.</p>
    <p style="font-size:12px;color:#9ca3af">${esc(cfg.businessDetails || '')}</p>`);
  out.push({
    json: {
      invoiceId, clientId, clientName: val(r, 'Client Name'), email, amountValue: toNumber(r['Monthly Fee']),
      currency: val(r, 'Currency') || cfg.currency || 'USD', dueDate: due.toISODate(), paymentLink: val(r, 'Payment Link'),
      period, subject: `Invoice ${invoiceId} from ${cfg.businessName} — ${amount} due ${due.toFormat('d LLL')}`, html,
    },
    pairedItem: { item: i },
  });
});
return out;
